BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL search_path=pg_catalog; SET LOCAL statement_timeout='20s'; SELECT jsonb_build_object('observedAt',clock_timestamp(),'readOnly',current_setting('transaction_read_only'),'profiles',(SELECT jsonb_build_object('count',count(*),'unknownPlan',count(*) FILTER(WHERE plan NOT IN('free','pro','business') OR plan IS NULL)) FROM public.profiles),'history',(SELECT jsonb_build_object('count',count(*),'invalidShape',count(*) FILTER(WHERE calculator_slug IS NULL OR btrim(calculator_slug)='' OR calculator_version IS NULL OR calculator_version<1 OR jsonb_typeof(input_data) IS DISTINCT FROM 'object' OR jsonb_typeof(output_data) IS DISTINCT FROM 'object')) FROM public.calculation_history),'scenarios',(SELECT jsonb_build_object('count',count(*),'foreignProjectBinding',count(*) FILTER(WHERE s.project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.calculation_projects p WHERE p.id=s.project_id AND p.user_id=s.user_id))) FROM public.saved_scenarios s),'incomingForeignKeys',(SELECT jsonb_agg(jsonb_build_object('relation',c.conrelid::regclass::text,'name',c.conname,'target',c.confrelid::regclass::text,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conname) FROM pg_constraint c WHERE c.contype='f' AND c.confrelid IN('public.profiles'::regclass,'public.calculation_history'::regclass,'public.calculation_projects'::regclass,'public.saved_scenarios'::regclass)),'functionReferenceCandidates',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'definitionSHA256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')) ORDER BY p.proname,oidvectortypes(p.proargtypes)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND (pg_get_functiondef(p.oid) ~ '(profiles|calculation_history|saved_scenarios|calculation_projects)')),'scopedLocks',(SELECT count(*) FROM pg_locks WHERE relation IN('public.profiles'::regclass,'public.calculation_history'::regclass,'public.calculation_projects'::regclass,'public.saved_scenarios'::regclass) AND pid IS DISTINCT FROM pg_backend_pid()),'preparedTransactions',(SELECT count(*) FROM pg_prepared_xacts WHERE database=current_database())) AS evidence; COMMIT;
